import * as vscode from "vscode";

// Shapes that may take |> extensions. No check for an actual call.
const EXTENDABLE = [
    /^(sif|maak|cima|khutla)\b.*!$/, // keyword statements
    /<-.*!$/, // reassignment
    /!$/, // expression / generic call / IIFE
];

/** Line content with strings respected and trailing @ comment removed. */
function codeOf(text: string): string {
    let inString = false;
    for (let i = 0; i < text.length; i++) {
        const c = text[i];
        if (inString) {
            if (c === "$") i++;
            else if (c === '"') inString = false;
            continue;
        }
        if (c === '"') inString = true;
        else if (c === "@") return text.slice(0, i);
    }
    return text;
}

/** head line -> last |> line of each extension chain. */
export function findExtensionChains(doc: vscode.TextDocument): Block[] {
    const chains: Block[] = [];
    let head = -1;
    let last = -1;

    const flush = () => {
        if (head >= 0 && last > head) chains.push({ open: head, close: last });
        head = last = -1;
    };

    for (let line = 0; line < doc.lineCount; line++) {
        const code = codeOf(doc.lineAt(line).text).trim();
        if (code === "") continue; // blank or comment-only

        if (code.startsWith("|>")) {
            // a |> line that opens a block would cross the block's fold range, so end the chain before it
            if (head >= 0 && !code.endsWith("->")) last = line;
            else flush();
            continue;
        }

        flush();
        head = EXTENDABLE.some((r) => r.test(code)) ? line : -1;
    }
    flush();
    return chains;
}

export interface Block {
    open: number; // line of ->
    close: number; // line of <~
}

/** Scans a document and returns every matched ->  <~ pair (nesting + chaining aware). */
export function findBlocks(doc: vscode.TextDocument): Block[] {
    const blocks: Block[] = [];
    const stack: number[] = [];

    for (let line = 0; line < doc.lineCount; line++) {
        const text = doc.lineAt(line).text;
        let inString = false;

        for (let i = 0; i < text.length; i++) {
            const c = text[i];

            if (inString) {
                if (c === "$") i++;
                else if (c === '"') inString = false;
                continue;
            }
            if (c === '"') {
                inString = true;
                continue;
            }
            if (c === "@") break; // comment (@ and @*) runs to end of line

            if (c === "-" && text[i + 1] === ">") {
                stack.push(line);
                i++;
            } else if (c === "<" && text[i + 1] === "~") {
                const open = stack.pop();
                if (open !== undefined) blocks.push({ open, close: line });
                i++;
            }
        }
    }
    return blocks;
}

/** Call once from activate(). Registers folding driven by the real block structure. */
export function registerJaivaBlocks(
    context: vscode.ExtensionContext,
    languageId = "jaiva",
) {
    context.subscriptions.push(
        vscode.languages.registerFoldingRangeProvider(languageId, {
            provideFoldingRanges(doc) {
                const blocks = findBlocks(doc)
                    .filter((b) => b.close - 1 > b.open)
                    .map((b) => new vscode.FoldingRange(b.open, b.close - 1));

                const chains = findExtensionChains(doc).map(
                    (c) => new vscode.FoldingRange(c.open, c.close),
                );

                return [...blocks, ...chains];
            },
        }),
    );
}
